// The list of the boxes of „Optionen“ that scripts/gen-features.ts writes
// (#378), in a file of its own: it imports nothing of the client, so a
// mutation run of the client logic does not run it against its sandbox, whose
// copy of the generated file starts with Stryker's `// @ts-nocheck`.
import {
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import {
  generateOptionBoxes,
  OPTION_BOXES_DIR,
  OPTION_BOXES_FILE,
  renderOptionBoxes,
  scanOptionBoxes,
} from '../../scripts/gen-features.ts';

describe('the list of the boxes of „Optionen“ (#378)', () => {
  let dir: string;
  const HEADER =
    '// Generated by scripts/gen-features.ts; not checked in, do not edit.\n';
  const write = (file: string, source = 'export const optionBoxes = [];\n') => {
    mkdirSync(path.dirname(path.join(dir, file)), { recursive: true });
    writeFileSync(path.join(dir, file), source);
  };

  beforeEach(() => {
    dir = path.join(mkdtempSync(path.join(tmpdir(), 'nova-')), 'options');
  });
  afterEach(() => rmSync(path.dirname(dir), { recursive: true, force: true }));

  it('is written before the tests run', () => {
    expect(
      readFileSync(path.join(OPTION_BOXES_DIR, OPTION_BOXES_FILE), 'utf8'),
    ).toBe(renderOptionBoxes(scanOptionBoxes(OPTION_BOXES_DIR)));
  });

  it('is empty but valid for an empty or missing folder', () => {
    const empty = `${HEADER}\nexport const OPTION_BOXES = [] as const;\n`;
    expect(scanOptionBoxes(dir)).toEqual([]);
    expect(generateOptionBoxes(dir)).toBe(true);
    expect(readFileSync(path.join(dir, OPTION_BOXES_FILE), 'utf8')).toBe(empty);
  });

  it('imports every file that exports optionBoxes, sorted, and writes only a change', () => {
    write('push.ts');
    write('account/delete.ts');
    write('other.ts', 'export const other = 1;\n');
    write('push.test.ts');
    write(OPTION_BOXES_FILE);
    write('x.ts', 'export const myoptionBoxes = [];\n');
    expect(scanOptionBoxes(dir)).toEqual(['account/delete.ts', 'push.ts']);
    expect(generateOptionBoxes(dir)).toBe(true);
    expect(generateOptionBoxes(dir)).toBe(false);
    expect(readFileSync(path.join(dir, OPTION_BOXES_FILE), 'utf8')).toBe(
      [
        HEADER,
        "import { optionBoxes as feature_account_delete } from './account/delete.ts';",
        "import { optionBoxes as feature_push } from './push.ts';",
        '',
        'export const OPTION_BOXES = [',
        "  ['account/delete', feature_account_delete],",
        "  ['push', feature_push],",
        '] as const;',
        '',
      ].join('\n'),
    );
  });
});
